// Geometry: 48 pixels to a ring, pixel 0 at twelve o'clock, clockwise.
const PIXELS = 48;
const STEP = 4;              // 4 pixels is one hour on the dial
const SECONDS_PER_STEP = 0.2;
const SLOT = 3;

const HEAD = 'white';
const TAIL = 'royal_blue';

const steps = [];

for (let i = 0; i < PIXELS / STEP; i++) {
    const head = (i * STEP) % PIXELS;
    const tail = (head - STEP + PIXELS) % PIXELS;
    const gone = (head - 2 * STEP + 2 * PIXELS) % PIXELS;

    steps.push({
        seconds: SECONDS_PER_STEP,
        segments: [
            // Anything drawn stays on screen after its step ends, so the
            // black segment is what makes this a comet instead of a ring
            // slowly filling up.
            { start: gone, length: STEP, ring: 0, rings_tall: 4, color: 'black' },
            { start: tail, length: STEP, ring: 0, rings_tall: 4, color: TAIL },
            { start: head, length: STEP, ring: 0, rings_tall: 4, color: HEAD },
        ],
    });
}

// Sweep up after yourself. Verified on hardware 2026-08-12: without this the
// head and tail stay lit where the last step left them, for the twelve
// seconds until the scene runs again.
const last = (PIXELS - STEP) % PIXELS;
steps.push({
    seconds: SECONDS_PER_STEP,
    segments: [
        { start: (last - STEP + PIXELS) % PIXELS, length: STEP, ring: 0, rings_tall: 4, color: 'black' },
        { start: last, length: STEP, ring: 0, rings_tall: 4, color: 'black' },
    ],
});

// Filmed on hardware: the head advances four pixels every 0.2s, clockwise,
// exactly as written. Twelve steps is 2.4 seconds of motion inside the
// clock's ~15 second cycle, so it then sits still for about twelve seconds.
// Pad the timeline out towards 15 seconds if you want continuous motion.

msg.action = 'glance_clock.set_scene';
msg.payload = {
    slot: SLOT,
    mode: 'watchface',
    steps: steps,
};
return msg;

// pulse, wave and light_flash do not draw anything themselves -- they
// modulate an area that has already been drawn in the same scene. So the
// effect step has to come after a fill covering the same area.
const SLOT = 3;
const COLOR = 'royal_blue';
const AREA = { start: 0, length: 48, ring: 0, rings_tall: 4, color: COLOR };

msg.action = 'glance_clock.set_scene';
msg.payload = {
    slot: SLOT,
    mode: 'watchface',
    steps: [
        { seconds: 0.2, segments: [AREA] },
        {
            type: 'effect',
            effect: 'pulse',
            rise: 20,
            fall: 80,
            seconds: 14,
            segments: [AREA],
        },
    ],
};
return msg;
